/* Calendar month transition (`animate` prop) Ã¢â‚¬â€ adapted from react-day-picker
   (MIT, https://github.com/gpbl/react-day-picker) style.css and namespaced so
   the kit never needs the rdp-* stylesheet. */
@keyframes kira-calendar-slide-in-left {
  from { transform: translateX(-100%); }
  to { transform: translateX(0); }
}

@keyframes kira-calendar-slide-in-right {
  from { transform: translateX(100%); }
  to { transform: translateX(0); }
}

@keyframes kira-calendar-slide-out-left {
  from { transform: translateX(0); }
  to { transform: translateX(-100%); }
}

@keyframes kira-calendar-slide-out-right {
  from { transform: translateX(0); }
  to { transform: translateX(100%); }
}

@keyframes kira-calendar-fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes kira-calendar-fade-out {
  from { opacity: 1; }
  to { opacity: 0; }
}

.kira-calendar-weeks-before-enter {
  animation: kira-calendar-slide-in-left var(--kira-calendar-animation-duration, 0.3s) var(--kira-calendar-animation-timing, cubic-bezier(0.4, 0, 0.2, 1)) forwards;
}

.kira-calendar-weeks-before-exit {
  animation: kira-calendar-slide-out-left var(--kira-calendar-animation-duration, 0.3s) var(--kira-calendar-animation-timing, cubic-bezier(0.4, 0, 0.2, 1)) forwards;
}

.kira-calendar-weeks-after-enter {
  animation: kira-calendar-slide-in-right var(--kira-calendar-animation-duration, 0.3s) var(--kira-calendar-animation-timing, cubic-bezier(0.4, 0, 0.2, 1)) forwards;
}

.kira-calendar-weeks-after-exit {
  animation: kira-calendar-slide-out-right var(--kira-calendar-animation-duration, 0.3s) var(--kira-calendar-animation-timing, cubic-bezier(0.4, 0, 0.2, 1)) forwards;
}

[dir="rtl"] .kira-calendar-weeks-after-enter {
  animation-name: kira-calendar-slide-in-left;
}

[dir="rtl"] .kira-calendar-weeks-before-exit {
  animation-name: kira-calendar-slide-out-right;
}

[dir="rtl"] .kira-calendar-weeks-before-enter {
  animation-name: kira-calendar-slide-in-right;
}

[dir="rtl"] .kira-calendar-weeks-after-exit {
  animation-name: kira-calendar-slide-out-left;
}

.kira-calendar-caption-before-enter,
.kira-calendar-caption-after-enter {
  animation: kira-calendar-fade-in var(--kira-calendar-animation-duration, 0.3s) var(--kira-calendar-animation-timing, cubic-bezier(0.4, 0, 0.2, 1)) forwards;
}

.kira-calendar-caption-before-exit,
.kira-calendar-caption-after-exit {
  animation: kira-calendar-fade-out var(--kira-calendar-animation-duration, 0.3s) var(--kira-calendar-animation-timing, cubic-bezier(0.4, 0, 0.2, 1)) forwards;
}

@media (prefers-reduced-motion: reduce) {
  [data-slot="calendar"],
  [data-slot="calendar"] * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

:root {
  --ease-spring: linear(0, 0.015, 0.0552, 0.1142, 0.1865, 0.2671, 0.352, 0.4379, 0.522, 0.6024, 0.6774, 0.7461, 0.8078, 0.8621, 0.9091, 0.9489, 0.9819, 1.0085, 1.0293, 1.0449, 1.056, 1.0631, 1.067, 1.0681, 1.067, 1.0642, 1.0601, 1.0552, 1.0497, 1.0439, 1.0381, 1.0324, 1.0269, 1.0218, 1.0171, 1.013, 1.0093, 1.0061, 1.0034, 1.0012, 0.9994, 0.998, 0.9969, 0.9962, 0.9957, 0.9954, 0.9954, 0.9954, 0.9956, 0.9959, 1);
}

@theme inline {
  --animate-route-fade: route-fade 0.15s cubic-bezier(0.23, 1, 0.32, 1) both;
  --animate-route-fade-up: route-fade-up 0.25s var(--ease-spring) both;
  --animate-route-fade-down: route-fade-down 0.25s var(--ease-spring) both;
  --animate-route-slide-left: route-slide-left 0.25s var(--ease-spring) both;
  --animate-route-slide-right: route-slide-right 0.25s var(--ease-spring) both;
  --animate-route-zoom: route-zoom 0.25s var(--ease-spring) both;
  --animate-nav-progress: nav-progress 10s ease-out forwards;
}

@keyframes route-fade {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes route-fade-up {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes route-fade-down {
  from { opacity: 0; transform: translateY(-8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes route-slide-left {
  from { opacity: 0; transform: translateX(24px); }
  to { opacity: 1; transform: translateX(0); }
}

@keyframes route-slide-right {
  from { opacity: 0; transform: translateX(-24px); }
  to { opacity: 1; transform: translateX(0); }
}

@keyframes route-zoom {
  from { opacity: 0; transform: scale(0.96); }
  to { opacity: 1; transform: scale(1); }
}

@keyframes nav-progress {
  0% { transform: scaleX(0); }
  15% { transform: scaleX(0.4); }
  40% { transform: scaleX(0.65); }
  70% { transform: scaleX(0.8); }
  100% { transform: scaleX(0.9); }
}

::view-transition-old(root),
::view-transition-new(root) {
  animation-duration: 150ms;
  animation-timing-function: cubic-bezier(0.23, 1, 0.32, 1);
}

@media (prefers-reduced-motion: reduce) {
  ::view-transition-old(root),
  ::view-transition-new(root) {
    animation-duration: 0.01ms;
  }

  [data-slot="route-transition"],
  [data-slot="navigation-progress"] {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}
